local GlassBatchMaker = {}
local PRODUCTS = {
    iron_glass_batch = { name = "Železna mešanica za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 175, prestige = 4, happiness = 2, description = "Železna mešanica za osnovno steklo." },
    bronze_glass_batch = { name = "Bronasta mešanica za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 425, prestige = 6, happiness = 3, description = "Bronasta mešanica za kvalitetno steklo." },
    silver_glass_batch = { name = "Srebrna mešanica za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1025, prestige = 11, happiness = 4, description = "Srebrna mešanica za plemiško steklo." },
    gilded_glass_batch = { name = "Pozlačena mešanica za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačena mešanica za dvorno steklo." },
    jewel_set_glass_batch = { name = "Draguljasta mešanica za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4750, prestige = 36, happiness = 7, description = "Draguljasta mešanica za kraljevsko steklo." },
    royal_sovereign_glass_batch = { name = "Kraljevski suverena mešanica za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suverena mešanica z biseri za krono." },
}
local BUILDINGS = {
    glassbatch_workshop = { name = "Mešalna delavnica", cost = { gold = 355, wood = 180, stone = 135, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    glassbatch_house = { name = "Mešalna hiša", cost = { gold = 1255, wood = 365, stone = 280, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_glassbatch_atelier = { name = "Mojstrski mešalni atelje", cost = { gold = 3140, wood = 425, stone = 530, silver = 37, gold = 7 }, upkeep = 74, qualityBonus = 30 },
    sovereign_glassbatch_palace = { name = "Suverena mešalna palača", cost = { gold = 13300, wood = 655, stone = 845, gold = 85, jewel = 19 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
GlassBatchMaker.ironStock = 14; GlassBatchMaker.bronzeStock = 12; GlassBatchMaker.woodStock = 12; GlassBatchMaker.leatherStock = 10; GlassBatchMaker.silverStock = 8; GlassBatchMaker.goldStock = 6; GlassBatchMaker.jewelStock = 4; GlassBatchMaker.pearlStock = 4
GlassBatchMaker.productStock = {}; GlassBatchMaker.buildings = {}; GlassBatchMaker.maker = nil; GlassBatchMaker.activeMaking = {}; GlassBatchMaker.totalProducts = 0; GlassBatchMaker.dayTimer = 0
function GlassBatchMaker.init() GlassBatchMaker.ironStock=14; GlassBatchMaker.bronzeStock=12; GlassBatchMaker.woodStock=12; GlassBatchMaker.leatherStock=10; GlassBatchMaker.silverStock=8; GlassBatchMaker.goldStock=6; GlassBatchMaker.jewelStock=4; GlassBatchMaker.pearlStock=4; GlassBatchMaker.productStock={}; GlassBatchMaker.buildings={}; GlassBatchMaker.maker=nil; GlassBatchMaker.activeMaking={}; GlassBatchMaker.totalProducts=0; GlassBatchMaker.dayTimer=0; print("[GlassBatchMaker] Royal Glass Batch Maker System initialized (6 products, 4 buildings)") end
function GlassBatchMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBatchMaker.maker={name=n or ("Mešalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mešalec najet: %s (spretnost: %d)",GlassBatchMaker.maker.name,s),"success") end; return true end
function GlassBatchMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBatchMaker.build(id) local ok,e=GlassBatchMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBatchMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBatchMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBatchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBatchMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassBatchMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassBatchMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassBatchMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassBatchMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassBatchMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBatchMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBatchMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBatchMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBatchMaker.buildings==0 then return false,"Potrebna mešalna delavnica" end; if not GlassBatchMaker.maker then return false,"Potreben mešalec" end; return true end
function GlassBatchMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBatchMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassBatchMaker.ironStock=GlassBatchMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassBatchMaker.bronzeStock=GlassBatchMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassBatchMaker.woodStock=GlassBatchMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassBatchMaker.leatherStock=GlassBatchMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassBatchMaker.silverStock=GlassBatchMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBatchMaker.goldStock=GlassBatchMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBatchMaker.jewelStock=GlassBatchMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBatchMaker.pearlStock=GlassBatchMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBatchMaker.maker then t=math.max(1,t-math.floor(GlassBatchMaker.maker.skill/13)) end; table.insert(GlassBatchMaker.activeMaking,{id="glassbatch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBatchMaker.completeMaking(m) local q=1.0+(GlassBatchMaker.getQualityBonus()/100); if GlassBatchMaker.maker then q=q+(GlassBatchMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBatchMaker.productStock[m.productType]=(GlassBatchMaker.productStock[m.productType] or 0)+m.quantity; GlassBatchMaker.totalProducts=GlassBatchMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBatchMaker.maker then GlassBatchMaker.maker.itemsMade=GlassBatchMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBatchMaker.maker.skill=math.min(100,GlassBatchMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mešanica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassbatch.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBatchMaker.update(dt) if not _G.state then return end; GlassBatchMaker.dayTimer=GlassBatchMaker.dayTimer+dt; if GlassBatchMaker.dayTimer>=30 then GlassBatchMaker.dayTimer=0; for i=#GlassBatchMaker.activeMaking,1,-1 do local m=GlassBatchMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBatchMaker.completeMaking(m); table.remove(GlassBatchMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBatchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBatchMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBatchMaker.getStats() return {ironStock=GlassBatchMaker.ironStock,bronzeStock=GlassBatchMaker.bronzeStock,woodStock=GlassBatchMaker.woodStock,leatherStock=GlassBatchMaker.leatherStock,silverStock=GlassBatchMaker.silverStock,goldStock=GlassBatchMaker.goldStock,jewelStock=GlassBatchMaker.jewelStock,pearlStock=GlassBatchMaker.pearlStock,productStock=GlassBatchMaker.productStock,numBuildings=#GlassBatchMaker.buildings,hasMaker=GlassBatchMaker.maker~=nil,makerName=GlassBatchMaker.maker and GlassBatchMaker.maker.name or "—",makerSkill=GlassBatchMaker.maker and GlassBatchMaker.maker.skill or 0,activeMaking=#GlassBatchMaker.activeMaking,totalProducts=GlassBatchMaker.totalProducts} end
return GlassBatchMaker
